 final LocalDate date=LocalDate.of(2026,10,29);final Point office=new Point("Office",0d,0d,100d);
 @BeforeEach void workModes(){var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());var audit=new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules());modes=new WorkModeRepository(jdbc,json);resolver=new WorkModeResolver(modes);policies=proxy(new WorkModeService(access,repository,new PositionRepository(jdbc),modes,resolver,audit,time));homes=proxy(new HomeAddressService(access,repository,modes,resolver,audit,time));geo=new WorkModeClock(modes,resolver,time);punches=proxy(new ClockService(new AttendanceAccess(access,repository,schedules),repository,schedules,attendance,audit,time,geo));}
 Assignment mode(String mode){return policies.save(admin,store,employee,UUID.randomUUID(),new AssignmentWrite(0L,date,mode,false));}
 SchedulingDtos.Schedule plan(){var shift=shifts.save(admin,store,UUID.randomUUID(),new SchedulingDtos.ShiftWrite(0L,"Day","09:00","17:00",false,"none",0,0,0,0,false,true));return roster.save(admin,store,UUID.randomUUID(),new SchedulingDtos.ScheduleWrite(0L,employee,shift.id(),date,"scheduled"));}
 Location here(){return new Location(0d,0d,10d,time.instant(),"");}
 @Test void onsiteRejectsMissingOutsideAndBadAccuracyThenStoresEvidenceAndReplays(){mode("onsite");policies.saveSite(admin,store,new SiteWrite(0L,office));var s=plan();time.at(s.startAt().toString());assertThatThrownBy(()->punches.punch(worker,store,UUID.randomUUID(),new ClockWrite(s.id(),"IN"))).extracting("code").isEqualTo("WORKFORCE_LOCATION_REQUIRED");assertThatThrownBy(()->punches.punch(worker,store,UUID.randomUUID(),new ClockWrite(s.id(),"IN",null,new Location(1d,1d,10d,time.instant(),"")))).extracting("code").isEqualTo("WORKFORCE_LOCATION_OUTSIDE");var command=UUID.randomUUID();var c=new ClockWrite(s.id(),"IN",null,here());var session=punches.punch(worker,store,command,c);assertThat(session.clockPolicy().mode()).isEqualTo("onsite");time.at(s.startAt().plusSeconds(200).toString());assertThat(punches.punch(worker,store,command,c)).isEqualTo(session);assertThat(jdbc.queryForObject("select count(*) from workforce_clock_locations where tenant_id=?",Integer.class,tenant)).isEqualTo(1);assertThatThrownBy(()->punches.punch(worker,store,command,new ClockWrite(s.id(),"IN",null,here()))).isInstanceOf(com.rpb.reservation.workforce.domain.WorkforceException.class);}
 @Test void fieldWorksWithoutCoordinatesAndFreeCannotPunch(){mode("field");var s=plan();time.at(s.startAt().toString());assertThat(punches.punch(worker,store,UUID.randomUUID(),new ClockWrite(s.id(),"IN"))).isNotNull();}
 @Test void freeHasNoMissingAttendanceOrArtificialApproval(){mode("free");var s=plan();time.at(s.endAt().plusSeconds(1).toString());var query=new AttendanceQueryService(access,new AttendanceAccess(access,repository,schedules),schedules,attendance,time,geo);assertThat(query.detail(admin,store,s.id()).attendance().anomalies()).containsExactly("EXEMPT");assertThat(query.home(worker,store).actions()).isEmpty();assertThatThrownBy(()->punches.punch(worker,store,UUID.randomUUID(),new ClockWrite(s.id(),"IN"))).extracting("code").isEqualTo("WORKFORCE_CLOCK_EXEMPT");
  var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());var source=new com.rpb.reservation.workforce.approval.ApprovalSources(attendance,new com.rpb.reservation.workforce.leave.LeaveRepository(jdbc),new com.rpb.reservation.workforce.calendar.CalendarRepository(jdbc),json,time,geo);var ar=new com.rpb.reservation.workforce.approval.ApprovalRepository(jdbc,json);var service=proxy(new com.rpb.reservation.workforce.approval.ApprovalService(access,new AttendanceAccess(access,repository,schedules),repository,schedules,ar,source,new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules()),time));var detail=service.detail(admin,store,s.id());assertThat(detail.canReview()).isFalse();assertThat(detail.row().exempt()).isTrue();assertThat(com.rpb.reservation.workforce.approval.ApprovalBoardService.normal(detail.row())).isFalse();assertThat(com.rpb.reservation.workforce.approval.ApprovalBoardService.category(detail.row(),false)).isEqualTo("exempt");assertThatThrownBy(()->service.approve(admin,store,s.id(),new com.rpb.reservation.workforce.approval.ApprovalDtos.ApprovalWrite(0L,detail.row().sourceFingerprint(),"Attempt"))).extracting("code").isEqualTo("WORKFORCE_CLOCK_EXEMPT");assertThat(ar.history(tenant,s.id())).isEmpty();}
 @Test void homeRequiresApprovalAndKeepsOldApprovedPointUntilNewEffectiveDate(){mode("home");var id=UUID.randomUUID();var requested=homes.submit(worker,store,id,new HomeWrite(office,date));assertThat(homes.submit(worker,store,id,new HomeWrite(office,date))).isEqualTo(requested);var s=plan();time.at(s.startAt().toString());assertThatThrownBy(()->punches.punch(worker,store,UUID.randomUUID(),new ClockWrite(s.id(),"IN",null,here()))).extracting("code").isEqualTo("WORKFORCE_HOME_ADDRESS_REQUIRED");time.at("2026-10-28T04:00:00Z");homes.decide(admin,store,id,new HomeDecision(1L,"approved","Checked address"));time.at(s.startAt().toString());var session=punches.punch(worker,store,UUID.randomUUID(),new ClockWrite(s.id(),"IN",null,here()));assertThat(session.clockPolicy().addressId()).isEqualTo(id);var newer=homes.submit(worker,store,UUID.randomUUID(),new HomeWrite(new Point("New",1d,1d,100d),date.plusDays(1)));homes.decide(admin,store,newer.id(),new HomeDecision(1L,"approved","New address"));assertThat(resolver.resolve(tenant,employee,store,date).point()).isEqualTo(office);time.at(s.endAt().toString());assertThat(punches.punch(worker,store,UUID.randomUUID(),new ClockWrite(s.id(),"OUT",null,here())).clockPolicy()).isEqualTo(session.clockPolicy());}
 @Test void exceptionsAreDatedImmutableAndDoNotGrantSalaryOrSelfReview(){var a=mode("field");assertThatThrownBy(()->policies.save(admin,store,employee,UUID.randomUUID(),new AssignmentWrite(a.version(),date,"free",false))).isInstanceOf(com.rpb.reservation.workforce.domain.WorkforceException.class);assertThatThrownBy(()->policies.page(worker,store,employee)).isInstanceOf(com.rpb.reservation.workforce.domain.WorkforceException.class);assertThatThrownBy(()->policies.save(worker,store,employee,UUID.randomUUID(),new AssignmentWrite(a.version(),date.plusDays(1),"free",false))).isInstanceOf(com.rpb.reservation.workforce.domain.WorkforceException.class);}
 @Test void evenElevatedApplicantCannotApproveOwnHomeAddress(){var a=homes.submit(worker,store,UUID.randomUUID(),new HomeWrite(office,date));var elevated=new com.rpb.reservation.walkin.api.CurrentActor(tenant,employeeAccount,"staff",Set.of("tenant_admin"),admin.permissions(),Set.of(store,sibling,otherStore));assertThatThrownBy(()->homes.decide(elevated,store,a.id(),new HomeDecision(1L,"approved","Self"))).isInstanceOf(com.rpb.reservation.workforce.domain.WorkforceException.class);}
 @Test void positionDefaultIsCopiedAndRenameDoesNotChangeEmployeePolicy(){var positions=proxy(new PositionService(access,new PositionRepository(jdbc),new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules())));var p=positions.save(admin,store,UUID.randomUUID(),new PositionDtos.PositionWrite(0L,"Remote",true,"field"));var e=repository.find(tenant,employee).orElseThrow();jdbc.update("update workforce_employees set position_id=? where tenant_id=? and id=?",p.id(),tenant,employee);var next=repository.find(tenant,employee).orElseThrow();policies.adoptPosition(admin,store,e,next,LocalDate.of(2026,10,28));positions.save(admin,store,p.id(),new PositionDtos.PositionWrite(1L,"Renamed",true,"free"));assertThat(resolver.resolve(tenant,employee,store,date).mode()).isEqualTo("field");}
 @Test void currentSessionPinsSiteVersionWhenAdministratorMovesTheSite(){mode("onsite");policies.saveSite(admin,store,new SiteWrite(0L,office));var s=plan();time.at(s.startAt().toString());var first=punches.punch(worker,store,UUID.randomUUID(),new ClockWrite(s.id(),"IN",null,here()));policies.saveSite(admin,store,new SiteWrite(1L,new Point("Moved",1d,1d,100d)));time.at(s.endAt().toString());var last=punches.punch(worker,store,UUID.randomUUID(),new ClockWrite(s.id(),"OUT",null,here()));assertThat(last.clockPolicy()).isEqualTo(first.clockPolicy());assertThat(last.clockPolicy().point()).isEqualTo(office);assertThat(last.clockPolicy().siteVersion()).isEqualTo(1L);}
 @Test void auditFailureRollsBackAddressDecisionAndDatedAssignment(){var h=homes.submit(worker,store,UUID.randomUUID(),new HomeWrite(office,date));org.mockito.Mockito.doThrow(new IllegalStateException("audit")).when(logs).append(org.mockito.ArgumentMatchers.any(com.rpb.reservation.common.scope.StoreScope.class),org.mockito.ArgumentMatchers.any());assertThatThrownBy(()->homes.decide(admin,store,h.id(),new HomeDecision(1L,"approved","Review"))).isInstanceOf(IllegalStateException.class);assertThat(modes.address(tenant,h.id()).orElseThrow().status()).isEqualTo("pending");assertThatThrownBy(()->mode("field")).isInstanceOf(IllegalStateException.class);assertThat(modes.assignments(tenant,employee)).isEmpty();}
 @Test void partialStoreManagerCannotReadHomePointThroughAttendanceOrApprovalHistory(){
  mode("home");var h=homes.submit(worker,store,UUID.randomUUID(),new HomeWrite(office,date));homes.decide(admin,store,h.id(),new HomeDecision(1L,"approved","Reviewed"));var s=plan();time.at(s.startAt().toString());punches.punch(worker,store,UUID.randomUUID(),new ClockWrite(s.id(),"IN",null,here()));time.at(s.endAt().toString());punches.punch(worker,store,UUID.randomUUID(),new ClockWrite(s.id(),"OUT",null,here()));
  var managerId=account("store_manager",Set.of(store),Set.of("workforce.view"));admins.save(admin,store,managerId,new WorkforceDtos.AdministratorWrite(0L,true,null));var manager=new com.rpb.reservation.walkin.api.CurrentActor(tenant,managerId,"staff",Set.of("store_manager"),Set.of("workforce.view"),Set.of(store));
  assertThatThrownBy(()->policies.page(manager,store,employee)).isInstanceOf(com.rpb.reservation.workforce.domain.WorkforceException.class);var privacy=new WorkModePrivacy(access,repository);var scope=new AttendanceAccess(access,repository,schedules);var query=new AttendanceQueryService(access,scope,schedules,attendance,time,geo,privacy);var response=query.detail(manager,store,s.id());assertThat(response.attendance().session().clockPolicy().point()).isNull();assertThat(response.events()).allMatch(e->e.location()==null);assertThat(attendance.bySchedule(tenant,s.id()).orElseThrow().clockPolicy().point()).isEqualTo(office);
  var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());var source=new com.rpb.reservation.workforce.approval.ApprovalSources(attendance,new com.rpb.reservation.workforce.leave.LeaveRepository(jdbc),new com.rpb.reservation.workforce.calendar.CalendarRepository(jdbc),json,time,geo);var ar=new com.rpb.reservation.workforce.approval.ApprovalRepository(jdbc,json);var service=proxy(new com.rpb.reservation.workforce.approval.ApprovalService(access,scope,repository,schedules,ar,source,new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules()),time,privacy));var full=service.detail(admin,store,s.id());service.approve(admin,store,s.id(),new com.rpb.reservation.workforce.approval.ApprovalDtos.ApprovalWrite(0L,full.row().sourceFingerprint(),"Reviewed"));var sanitized=service.detail(manager,store,s.id());assertThat(sanitized.history().getFirst().snapshot().clockPolicy().point()).isNull();assertThat(sanitized.history().getFirst().snapshot().session().clockPolicy().point()).isNull();assertThat(sanitized.row().sourceFingerprint()).isEqualTo(full.row().sourceFingerprint());assertThat(ar.history(tenant,s.id()).getFirst().snapshot().clockPolicy().point()).isEqualTo(office);
 }
 @Test void employeeSaveAdoptsPositionDefaultButLaterPositionChangePreservesPersonalException(){
  var audit=new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules());var positionRepo=new PositionRepository(jdbc);var positionService=proxy(new PositionService(access,positionRepo,audit));var p=positionService.save(admin,store,UUID.randomUUID(),new PositionDtos.PositionWrite(0L,"New remote",true,"field"));
  var service=proxy(new WorkforceEmployeeService(access,directory,repository,new com.rpb.reservation.auth.application.WorkforceAccountProvisioner(jdbc,new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder()),audit,time,new EmployeePositionSelection(positionRepo),policies));var seed=command(0,List.of(store,sibling),company,null,null);var id=UUID.randomUUID();
  var first=service.save(admin,store,id,new WorkforceDtos.EmployeeWrite(0L,"MODE001",seed.name(),seed.phone(),seed.email(),seed.jobTitle(),seed.hireDate(),null,"active",company,seed.companyEffectiveDate(),store,seed.storeIds(),null,null,null,p.id()));assertThat(resolver.resolve(tenant,id,store,LocalDate.of(2026,10,28)).mode()).isEqualTo("field");
  policies.save(admin,store,id,UUID.randomUUID(),new AssignmentWrite(1L,date,"free",false));var other=positionService.save(admin,store,UUID.randomUUID(),new PositionDtos.PositionWrite(0L,"New onsite",true,"onsite"));service.save(admin,store,id,new WorkforceDtos.EmployeeWrite(first.version(),"MODE001",seed.name(),seed.phone(),seed.email(),seed.jobTitle(),seed.hireDate(),null,"active",company,seed.companyEffectiveDate(),store,seed.storeIds(),null,null,null,other.id()));assertThat(resolver.resolve(tenant,id,store,date).mode()).isEqualTo("free");
  var inherited=policies.save(admin,store,id,UUID.randomUUID(),new AssignmentWrite(2L,date.plusDays(1),"legacy",true));assertThat(inherited.positionId()).isEqualTo(other.id());assertThat(inherited.origin()).isEqualTo("position");assertThat(resolver.resolve(tenant,id,store,date.plusDays(1)).mode()).isEqualTo("onsite");
 }
 @Test void payrollRejectsModeMismatchAndUsesFixedSalaryInNextFullFreeMonth(){
  mode("free");var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());var newSources=new com.rpb.reservation.workforce.payroll.PayrollSources(payRepository,configs,repository,schedules,new com.rpb.reservation.workforce.approval.ApprovalRepository(jdbc,json),new com.rpb.reservation.workforce.approval.ApprovalSources(attendance,new com.rpb.reservation.workforce.leave.LeaveRepository(jdbc),new com.rpb.reservation.workforce.calendar.CalendarRepository(jdbc),json,time,geo),json,resolver);assertThat(newSources.capture(tenant,company,java.time.YearMonth.of(2026,10),List.of()).lines().getFirst().issues()).contains("WORK_MODE_PAYROLL_MISMATCH","WORK_MODE_MONTH_SPLIT");
  var fixed=new com.rpb.reservation.workforce.payroll.PayrollDtos.Rule("monthly","3000","8","44",false,"1.5",List.of(),new com.rpb.reservation.workforce.payroll.PayrollDtos.Generation("fixed",List.of()));configuration.saveProfile(admin,store,profile,new com.rpb.reservation.workforce.payroll.PayrollDtos.ProfileWrite(1L,company,employee,LocalDate.of(2026,10,1),template,fixed,new com.rpb.reservation.workforce.statutory.StatutoryDtos.CpfProfile("foreign",null,null,"GG","")));time.at("2026-12-02T01:00:00Z");var capture=newSources.capture(tenant,company,YearMonth.of(2026,11),List.of());var calculation=new com.rpb.reservation.workforce.payroll.PayrollCalculationService(time).calculate(capture,YearMonth.of(2026,11));assertThat(calculation.issues()).isEmpty();assertThat(calculation.lines().getFirst().basicPay()).isEqualTo("3000.00");
 }
 @Test void concurrentPolicyUpdatesCannotOverwriteTheWinningVersion()throws Exception{
  var pool=java.util.concurrent.Executors.newFixedThreadPool(2);var start=new java.util.concurrent.CountDownLatch(1);try{var calls=new ArrayList<java.util.concurrent.Future<Boolean>>();for(var name:List.of("field","home"))calls.add(pool.submit(()->{start.await();try{policies.save(admin,store,employee,UUID.randomUUID(),new AssignmentWrite(0L,date,name,false));return true;}catch(com.rpb.reservation.workforce.domain.WorkforceException e){assertThat(e.code()).isEqualTo("WORKFORCE_CONFLICT");return false;}}));start.countDown();int successes=0;for(var call:calls)if(call.get(20,java.util.concurrent.TimeUnit.SECONDS))successes++;assertThat(successes).isEqualTo(1);assertThat(modes.assignments(tenant,employee)).hasSize(1);}finally{pool.shutdownNow();}
 }
 @Test void rejectedHomeRequestIsImmutableAndCannotBeUsedForClocking(){mode("home");var id=UUID.randomUUID();var request=new HomeWrite(office,date);homes.submit(worker,store,id,request);var rejected=homes.decide(admin,store,id,new HomeDecision(1L,"rejected","Wrong address"));assertThat(homes.decide(admin,store,id,new HomeDecision(1L,"rejected","Wrong address"))).isEqualTo(rejected);assertThat(homes.submit(worker,store,id,request)).isEqualTo(rejected);assertThatThrownBy(()->homes.submit(worker,store,id,new HomeWrite(new Point("Changed",1d,1d,100d),date))).isInstanceOf(com.rpb.reservation.workforce.domain.WorkforceException.class);assertThat(resolver.resolve(tenant,employee,store,date).point()).isNull();}
 @Test void tenantForeignKeysAndAppGateDenyNewManagementPaths(){
  var foreign=UUID.randomUUID();jdbc.update("insert into tenants(id,tenant_code,display_name,status) values(?,?,'Foreign','active')",foreign,"foreign-"+foreign);assertThatThrownBy(()->modes.insert(foreign,new Assignment(UUID.randomUUID(),employee,date,"field","personal",null,0,1))).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);
  for(var reason:List.of(com.rpb.reservation.appgate.domain.AppGateDenyReason.APP_DISABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.TENANT_APP_NOT_ENABLED,com.rpb.reservation.appgate.domain.AppGateDenyReason.STORE_APP_NOT_ENABLED)){
   org.mockito.Mockito.doAnswer(c->{com.rpb.reservation.appgate.application.AppGateAccessRequest r=c.getArgument(0);return com.rpb.reservation.appgate.domain.AppGateDecision.deny(r.appKey(),r.tenantId(),r.storeId(),r.requiredPermission(),reason);}).when(gate).evaluate(org.mockito.ArgumentMatchers.any());assertThatThrownBy(()->policies.page(admin,store,employee)).extracting("code").isEqualTo(reason.name());assertThatThrownBy(()->homes.submit(worker,store,UUID.randomUUID(),new HomeWrite(office,date))).extracting("code").isEqualTo(reason.name());assertThatThrownBy(()->policies.saveSite(admin,store,new SiteWrite(0L,office))).extracting("code").isEqualTo(reason.name());
  }
 }
